static pthread_mutex_t mu = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t stamp;              /* attr: clock = CLOCK_MONOTONIC */
static struct timespec last_seen;
/* arrival path: lock(mu); clock_gettime(CLOCK_MONOTONIC, &last_seen); signal(stamp); unlock(mu); */
for (;;) {
    struct timespec deadline = add_ms(last_seen, period_ms);   /* last_seen + budget */
    int rc = pthread_cond_timedwait(&stamp, &mu, &deadline);
    if (rc == ETIMEDOUT)
        alert("no message on %s for %d ms", subject, period_ms);
}

